//! Phase 4 agreement probe — **how fast does a short search converge to
//! the answer of a long search?**
//!
//! The tactics probe (mates and free material) saturates at a few hundred
//! nodes: it cannot separate two selection rules once the budget grows.
//! This probe has far more statistical power:
//!
//! 1. a corpus of positions is generated by **random playouts** from the
//!    initial position (deterministic seed, so the corpus is
//!    reproducible);
//! 2. each position is solved by a **reference search** — the incumbent
//!    engine (the legacy UCT rule) with a long budget. The reference is
//!    the *baseline to beat*: the question is not "is the answer right"
//!    (there is no ground truth here) but "does a short search find the
//!    same move as a long one, and sooner";
//! 3. for each policy and each budget, the probe reports
//!    * the **agreement rate** with the reference (same best move);
//!    * the **mean score error** against the reference score.
//!
//! A policy that converges faster has a higher agreement rate and a lower
//! score error at the same node budget.
//!
//! ```text
//! cargo run --release --example mcts_agreement -- <ref_nodes> <positions> [budgets...]
//! ```

use mychess::mcts::{Limits, Policy, Rng, Search};
use mychess::movegen::{MoveList, generate};
use mychess::position::Position;
use mychess::types::{GenKind, Move};
use std::sync::atomic::AtomicBool;

/// The seed of the corpus generator (the corpus is reproducible).
const CORPUS_SEED: u64 = 0x00C0_FFEE_1234_5678;
/// The number of random plies of a generated game.
const GAME_PLIES: u32 = 60;

fn legal_moves(pos: &Position) -> Vec<Move> {
    let mut list = MoveList::new();
    generate(pos, &mut list, GenKind::All);
    list.iter().collect()
}

/// The corpus: positions reached by random playouts, one every
/// `stride` plies of each game.
///
/// `tactical` keeps only the positions where the side to move has a
/// **capture or a promotion** available: that is where a heuristic prior
/// (MVV-LVA) is supposed to make a difference, and a corpus of quiet
/// positions cannot show it.
fn corpus(count: usize, tactical: bool) -> Vec<Position> {
    let mut rng = Rng::new(CORPUS_SEED);
    let mut out = Vec::with_capacity(count);
    let mut game = 0u32;
    while out.len() < count {
        let mut pos = Position::startpos();
        for ply in 0..GAME_PLIES {
            let moves = legal_moves(&pos);
            if moves.is_empty() {
                break;
            }
            let pick = (rng.next_u64() % moves.len() as u64) as usize;
            pos.make(moves[pick]);
            // One position every 6 plies, and never the last one (an
            // exhausted game would be a trivial position).
            if ply % 6 == 3 && ply + 6 < GAME_PLIES {
                let interesting = !tactical
                    || legal_moves(&pos)
                        .iter()
                        .any(|m| m.is_capture() || m.is_promotion());
                if interesting {
                    out.push(pos);
                    if out.len() == count {
                        break;
                    }
                }
            }
        }
        game += 1;
        if game > 10_000 {
            break;
        }
    }
    out
}

fn limits(nodes: u64) -> Limits {
    Limits {
        nodes,
        movetime_ms: None,
        max_playout_ply: 100,
        c_uct: std::f32::consts::SQRT_2,
        c_puct: mychess::mcts::DEFAULT_C_PUCT,
        root_noise: mychess::mcts::DEFAULT_ROOT_NOISE,
        leaf_q: 0,
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let ref_nodes: u64 = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(60_000);
    let count: usize = args.get(2).and_then(|s| s.parse().ok()).unwrap_or(120);
    let budgets: Vec<u64> = args.iter().skip(3).filter_map(|s| s.parse().ok()).collect();
    let budgets = if budgets.is_empty() {
        vec![500, 2_000, 10_000, 40_000]
    } else {
        budgets
    };
    // The PUCT exploration constants to sweep: the **last** argument, if it
    // contains a comma (e.g. "0.5,1.5,3"). The legacy UCT rule does not
    // use them.
    let mut c_pucts: Vec<f32> = match args.last() {
        Some(last) if last.contains(',') => last
            .split(',')
            .filter_map(|x| x.trim().parse::<f32>().ok())
            .collect(),
        _ => Vec::new(),
    };
    if c_pucts.is_empty() {
        c_pucts = vec![mychess::mcts::DEFAULT_C_PUCT];
    }

    let tactical = args.iter().any(|s| s == "tactical");
    let threads: usize = args
        .iter()
        .find_map(|s| s.strip_prefix("threads="))
        .and_then(|s| s.parse().ok())
        .unwrap_or(1);
    let positions = corpus(count, tactical);
    println!(
        "# corpus: {} positions (seed {CORPUS_SEED:#x}, {}, {threads} thread(s))",
        positions.len(),
        if tactical {
            "tactical only"
        } else {
            "all positions"
        }
    );
    println!("# reference: the legacy UCT rule at {ref_nodes} nodes");

    // --- the reference ------------------------------------------------------
    let mut reference: Vec<(Move, i32)> = Vec::with_capacity(positions.len());
    for pos in &positions {
        let o = Search::new(*pos, vec![pos.zobrist], limits(ref_nodes), 42)
            .with_policy(Policy::Uct)
            .run(&AtomicBool::new(false));
        reference.push((o.best, o.score_cp));
    }

    // --- the short searches -------------------------------------------------
    for budget in &budgets {
        // The legacy UCT rule (the baseline).
        {
            let mut agree = 0usize;
            let mut err_sum = 0i64;
            let mut n = 0usize;
            for (pos, (ref_move, ref_score)) in positions.iter().zip(reference.iter()) {
                let o = Search::new(*pos, vec![pos.zobrist], limits(*budget), 42)
                    .with_policy(Policy::Uct)
                    .with_threads(threads)
                    .run(&AtomicBool::new(false));
                if o.best == *ref_move {
                    agree += 1;
                }
                err_sum += (o.score_cp - ref_score).abs() as i64;
                n += 1;
            }
            println!(
                "# budget {budget} policy uct: agreement {agree}/{n} ({:.1} %), mean |score error| {:.1} cp",
                100.0 * agree as f64 / n as f64,
                err_sum as f64 / n as f64
            );
        }
        // The PUCT rule, for every explored constant.
        for c_puct in &c_pucts {
            let mut agree = 0usize;
            let mut err_sum = 0i64;
            let mut n = 0usize;
            for (pos, (ref_move, ref_score)) in positions.iter().zip(reference.iter()) {
                let mut lim = limits(*budget);
                lim.c_puct = *c_puct;
                let o = Search::new(*pos, vec![pos.zobrist], lim, 42)
                    .with_policy(Policy::Puct)
                    .with_threads(threads)
                    .run(&AtomicBool::new(false));
                if o.best == *ref_move {
                    agree += 1;
                }
                err_sum += (o.score_cp - ref_score).abs() as i64;
                n += 1;
            }
            println!(
                "# budget {budget} policy puct (c_puct {c_puct}): agreement {agree}/{n} ({:.1} %), mean |score error| {:.1} cp",
                100.0 * agree as f64 / n as f64,
                err_sum as f64 / n as f64
            );
        }
    }
}
